/**
 * Updates subscription to a different tier or billing interval. Handles proration automatically.
 * @summary Update subscription tier
 */
export const updatePaddleSubscription = (
    updateSubscriptionInputBody: BodyType<NonReadonly<UpdateSubscriptionInputBody>>,
 options?: SecondParameter<typeof customInstance>,signal?: AbortSignal
) => {


      return customInstance<UpdateSubscriptionOutputBody>(
      {url: `/api/v1/subscription/update`, method: 'POST',
      headers: {'Content-Type': 'application/json', },
      data: updateSubscriptionInputBody, signal
    },
      options);
    }




export const getUpdatePaddleSubscriptionQueryKey = (updateSubscriptionInputBody?: BodyType<NonReadonly<UpdateSubscriptionInputBody>>,) => {
    return [
    'POST', `/api/v1/subscription/update`, updateSubscriptionInputBody
    ] as const;
    }


export const getUpdatePaddleSubscriptionQueryOptions = <TData = Awaited<ReturnType<typeof updatePaddleSubscription>>, TError = ErrorType<ErrorModel>>(updateSubscriptionInputBody: BodyType<NonReadonly<UpdateSubscriptionInputBody>>, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof updatePaddleSubscription>>, TError, TData>>, request?: SecondParameter<typeof customInstance>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getUpdatePaddleSubscriptionQueryKey(updateSubscriptionInputBody);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof updatePaddleSubscription>>> = ({ signal }) => updatePaddleSubscription(updateSubscriptionInputBody, requestOptions, signal);





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof updatePaddleSubscription>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

